import Link from 'next/link';
import { useRouter } from 'next/router';
import { useState } from 'react';

export default function Header() {
  const router = useRouter();
  const [mobileOpen, setMobileOpen] = useState(false);

  const links = [
    { name: 'Home', path: '/' },
    { name: 'Projetos', path: '/projetos' },
    { name: 'Habilidades', path: '/habilidades' },
    { name: 'Estudos', path: '/estudos' },
    { name: 'Certificados', path: '/certificados' },
    { name: 'Blog', path: '/blog' }
  ];

  return (
    <header style={headerStyle}>
      <div className="container" style={containerStyle}>
        <Link href="/" style={logoStyle}>
          <span className="neon-text">&lt;</span>Nicolas Almir<span className="neon-text">/&gt;</span>
        </Link>

        {/* Menu Desktop */}
        <nav style={desktopNavStyle}>
          {links.map((link) => (
            <Link key={link.path} href={link.path} style={{
              ...linkStyle,
              color: router.pathname === link.path ? 'var(--primary-color)' : 'var(--text-primary)',
              borderBottom: router.pathname === link.path ? '2px solid var(--primary-color)' : 'none'
            }}>
              {link.name}
            </Link>
          ))}
        </nav>

        {/* Botao Mobile */}
        <button onClick={() => setMobileOpen(!mobileOpen)} style={mobileBtnStyle}>
          <i className={`fas ${mobileOpen ? 'fa-times' : 'fa-bars'}`}></i>
        </button>
      </div>

      {/* Menu Mobile */}
      {mobileOpen && (
        <nav className="glass-panel" style={mobileNavStyle}>
          {links.map((link) => (
            <Link key={link.path} href={link.path} style={{
              display: 'block', padding: '15px 20px', 
              color: router.pathname === link.path ? 'var(--primary-color)' : 'var(--text-primary)'
            }} onClick={() => setMobileOpen(false)}>
              {link.name}
            </Link>
          ))}
        </nav>
      )}
    </header>
  );
}

const headerStyle = {
  position: 'fixed', top: 0, left: 0, width: '100%',
  background: 'rgba(5, 5, 5, 0.8)', backdropFilter: 'blur(10px)',
  borderBottom: '1px solid var(--surface-border)', zIndex: 1000
};
const containerStyle = { display: 'flex', justifyContent: 'space-between', alignItems: 'center', height: '80px' };
const logoStyle = { fontSize: '1.5rem', fontWeight: '700', letterSpacing: '1px' };
const desktopNavStyle = { display: 'flex', gap: '2rem' };
const linkStyle = { fontWeight: '500', transition: 'color 0.3s', paddingBottom: '5px' };
const mobileBtnStyle = { display: 'none', background: 'none', border: 'none', color: 'var(--text-primary)', fontSize: '1.5rem', cursor: 'pointer' };
const mobileNavStyle = { position: 'absolute', top: '80px', left: '20px', right: '20px', display: 'flex', flexDirection: 'column' };

// Para ocultar o botao mobile no desktop usando media query em JS simples (O ideal e via CSS puro, mas mantemos o padrao do seu Next.js)
if (typeof window !== 'undefined') {
  const style = document.createElement('style');
  style.innerHTML = `@media (min-width: 769px) { button[style*="display: none"] { display: none !important; } } @media (max-width: 768px) { nav[style*="display: flex; gap: 2rem;"] { display: none !important; } button[style*="display: none"] { display: block !important; } }`;
  document.head.appendChild(style);
}